import { useEffect, useMemo, useState } from "react";
import { fetchProducts } from "@/lib/api";
import { ArrowUp, SlidersHorizontal, X } from "lucide-react";

const BESTSELLERS = [
  "gulab-jamun", "jalebi", "kaju-katli", "motichoor-laddoo",
  "kaju-kharbooja", "kaju-anjeer-barfi", "kaju-roll", "soan-papdi"
];

export default function ProductsPage() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState("All");
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState("default");
  const [maxPrice, setMaxPrice] = useState(2000);
  const [showFilters, setShowFilters] = useState(false);
  const [showTop, setShowTop] = useState(false);

  useEffect(() => {
    let active = true;
    fetchProducts()
      .then((data) => active && setProducts(data))
      .catch(() => active && setProducts([]))
      .finally(() => active && setLoading(false));
    return () => { active = false; };
  }, []);

  useEffect(() => {
    const onScroll = () => setShowTop(window.scrollY > 400);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const highestPrice = useMemo(
    () => Math.max(...products.map((p) => p.price_inr), 2000),
    [products]
  );

  const categories = useMemo(() => {
    const set = new Set(products.map((p) => p.category));
    return ["All", ...Array.from(set)];
  }, [products]);

  const visible = useMemo(() => {
    let result = products
      .filter((p) => activeCategory === "All" || p.category === activeCategory)
      .filter((p) => p.name.toLowerCase().includes(search.toLowerCase()))
      .filter((p) => p.price_inr <= maxPrice);

    if (sortBy === "price-asc") result = [...result].sort((a, b) => a.price_inr - b.price_inr);
    if (sortBy === "price-desc") result = [...result].sort((a, b) => b.price_inr - a.price_inr);

    return result;
  }, [products, activeCategory, search, sortBy, maxPrice]);

  return (
    <div data-testid="products-page" className="bg-brand-ivory">

      {/* Header */}
      <section className="bg-brand-cream border-b border-brand-border">
        <div className="max-w-7xl mx-auto px-6 lg:px-10 py-20 md:py-28 text-center">
          <span className="divider-ornament">Our Counter</span>
          <h1
            className="font-serif text-brand-maroon text-5xl sm:text-6xl lg:text-7xl mt-5"
            data-testid="products-title"
          >
            The Mithai Menu
          </h1>
          <p className="mt-6 max-w-2xl mx-auto text-brand-text/75 leading-relaxed">
            From syrup-soaked classics to ghee-rich fudges, every sweet here is
            handmade in small batches at our heritage kitchen.
          </p>
        </div>
      </section>

      {/* Sticky filters bar */}
      <section className="border-b border-brand-border bg-brand-ivory sticky top-20 z-30">
        <div className="max-w-7xl mx-auto px-6 lg:px-10 py-4 flex flex-col gap-4">

          {/* Search + sort + filter toggle row */}
          <div className="flex flex-col sm:flex-row gap-3 items-center">
            <input
              type="text"
              placeholder="Search sweets..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full sm:max-w-xs px-5 py-2.5 border border-brand-border rounded-sm text-sm text-brand-text bg-brand-cream focus:outline-none focus:border-brand-maroon placeholder:text-brand-text/40"
            />
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="w-full sm:w-auto px-4 py-2.5 border border-brand-border rounded-sm text-sm text-brand-text bg-brand-cream focus:outline-none focus:border-brand-maroon"
            >
              <option value="default">Sort: Default</option>
              <option value="price-asc">Price: Low to High</option>
              <option value="price-desc">Price: High to Low</option>
            </select>
            <button
              type="button"
              onClick={() => setShowFilters((v) => !v)}
              className={`w-full sm:w-auto inline-flex items-center justify-center gap-2 px-4 py-2.5 border rounded-sm text-sm font-medium transition-colors ${
                showFilters
                  ? "bg-brand-maroon text-brand-ivory border-brand-maroon"
                  : "border-brand-border text-brand-text/70 hover:border-brand-maroon hover:text-brand-maroon"
              }`}
            >
              <SlidersHorizontal size={14} />
              Filters
            </button>
          </div>

          {/* Price range filter — shown when filters open */}
          {showFilters && (
            <div className="bg-brand-cream border border-brand-border rounded-sm px-6 py-4 flex flex-col sm:flex-row sm:items-center gap-4">
              <span className="text-[11px] tracking-[0.25em] uppercase text-brand-text/70 shrink-0">
                Max Price
              </span>
              <input
                type="range"
                min={0}
                max={highestPrice}
                step={50}
                value={maxPrice}
                onChange={(e) => setMaxPrice(Number(e.target.value))}
                className="flex-1 accent-brand-maroon"
              />
              <span className="text-brand-maroon font-serif text-lg shrink-0">
                ₹{maxPrice}
              </span>
              <button
                type="button"
                onClick={() => { setMaxPrice(highestPrice); setSortBy("default"); setSearch(""); setActiveCategory("All"); }}
                className="text-xs text-brand-text/50 hover:text-brand-maroon underline shrink-0"
              >
                Reset all
              </button>
            </div>
          )}

          {/* Category buttons */}
          <div className="flex flex-wrap gap-2 justify-center">
            {categories.map((cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => setActiveCategory(cat)}
                className={`px-5 py-2 rounded-sm uppercase text-[11px] tracking-[0.22em] font-medium transition-colors border ${
                  activeCategory === cat
                    ? "bg-brand-maroon text-brand-ivory border-brand-maroon"
                    : "bg-transparent text-brand-text/70 border-brand-border hover:border-brand-maroon hover:text-brand-maroon"
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Product count */}
          {!loading && (
            <p className="text-center text-xs text-brand-text/50 tracking-wide">
              Showing <span className="text-brand-maroon font-medium">{visible.length}</span> of{" "}
              <span className="text-brand-maroon font-medium">{products.length}</span> sweets
            </p>
          )}
        </div>
      </section>

      {/* Products grid */}
      <section className="max-w-7xl mx-auto px-6 lg:px-10 py-20">
        {loading ? (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="rounded-sm overflow-hidden border border-brand-border">
                <div className="aspect-[4/5] bg-brand-cream animate-pulse" />
                <div className="p-5 space-y-3 bg-brand-cream">
                  <div className="h-3 w-16 bg-brand-border rounded animate-pulse" />
                  <div className="h-5 w-32 bg-brand-border rounded animate-pulse" />
                  <div className="h-4 w-20 bg-brand-border rounded animate-pulse" />
                </div>
              </div>
            ))}
          </div>
        ) : visible.length === 0 ? (
          // Empty state
          <div className="flex flex-col items-center justify-center py-32 text-center">
            <span className="text-5xl mb-6">🍬</span>
            <h3 className="font-serif text-brand-maroon text-3xl mb-3">
              No sweets found
            </h3>
            <p className="text-brand-text/60 max-w-sm mb-8">
              We couldn't find any mithai matching your search. Try a different
              name or reset the filters.
            </p>
            <button
              type="button"
              onClick={() => { setSearch(""); setActiveCategory("All"); setMaxPrice(highestPrice); setSortBy("default"); }}
              className="inline-flex items-center gap-2 px-6 py-3 bg-brand-maroon text-brand-ivory rounded-sm uppercase text-xs tracking-[0.2em] hover:bg-brand-maroon-dark transition-colors"
            >
              <X size={14} />
              Reset Filters
            </button>
          </div>
        ) : (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
            {visible.map((p, i) => (
              <article
                key={p.id}
                className="group flex flex-col opacity-0 animate-fade-up"
                style={{ animationDelay: `${i * 40}ms`, animationFillMode: "forwards" }}
              >
                {/* Image with hover description overlay */}
                <div className="relative aspect-[4/5] overflow-hidden bg-brand-cream rounded-sm border border-brand-border">
                  <img
                    src={p.image_url}
                    alt={p.name}
                    loading="lazy"
                    className="h-full w-full object-cover group-hover:scale-105 transition-transform duration-700"
                  />
                  {/* Bestseller badge */}
                  {BESTSELLERS.includes(p.id) && (
                    <div className="absolute top-3 left-3 bg-brand-gold text-brand-maroon-deep text-[10px] tracking-[0.2em] uppercase font-medium px-3 py-1 rounded-sm">
                      Bestseller
                    </div>
                  )}
                  {/* Hover description overlay */}
                  <div className="absolute inset-0 bg-brand-maroon-deep/85 flex items-center justify-center p-6 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                    <p className="text-brand-ivory/90 text-sm leading-relaxed text-center">
                      {p.description}
                    </p>
                  </div>
                </div>

                {/* Card info */}
                <div className="pt-5 flex items-start justify-between gap-4">
                  <div>
                    <div className="text-[10px] tracking-[0.3em] uppercase text-brand-gold mb-1.5">
                      {p.category}
                    </div>
                    <h3 className="font-serif text-2xl text-brand-text">
                      {p.name}
                    </h3>
                  </div>
                  <div className="text-right shrink-0">
                    <div className="font-serif text-2xl text-brand-maroon">
                      ₹{p.price_inr}
                    </div>
                    <div className="text-[10px] tracking-[0.25em] uppercase text-brand-text/60">
                      {p.unit}
                    </div>
                  </div>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>

      {/* Back to top */}
      {showTop && (
        <button
          onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
          className="fixed bottom-8 right-8 z-50 h-12 w-12 rounded-full bg-brand-maroon text-brand-ivory shadow-lg flex items-center justify-center hover:bg-brand-maroon-dark transition-colors"
          aria-label="Back to top"
        >
          <ArrowUp size={20} />
        </button>
      )}
    </div>
  );
}
